(87, 1, 'شقه دوبلكس الزمالك', 'شقة دورين ٧٠٠ م  Penthouse  بالزمالك لراغبي السكن الراقي، ترى النيل باجمل اطلالة علي القاهرة في الدورين ال ١٣ وال ١٤. \r\n٥ غرف نوم. \r\n٥ حمام. \r\nالريسبشن ٥ صالون + سفرة طعام. \r\n٢ مطبخ + اوفيس. \r\nعدد ٢ غرف خدمات بالرووف الخاص في الدور ١٥. \r\nتراس بانوراما بالريسبشن. \r\nتراس بالرووف.', 'بينتهاوس', 700.00, NULL, 'available', 'Resale', '2025-09-15 16:09:09', 7, '5 غرف +5 حمام +ريسشيبن 5 قطع +2 م', 4, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'الزمالك', 'القاهره', '', 15, '', '14', NULL, NULL, 30000000.00, NULL, NULL, NULL, 'مالك', 'احمد فاروق', '1001649955', '', '', '', '', 30.05590530, 31.24237090),
(88, 1, 'شقه ميدان الاحرار', 'شقه رقم 92 \r\n✅ تشطيب فاخر ومناسب للسكن العائلي المميز أو المكاتب الإدارية.\r\n✅ موقع استراتيجي قريب من جميع الخدمات والمحاور الرئيسية.\r\n✅ الدور التاسع بواجهة مفتوحة وإطلالة بانورامية رائعة.', '19 شارع الأحرار – متفرع من البطل أحمد عبد العزيز', 470.00, NULL, 'available', 'Resale', '2025-09-16 11:06:28', 7, '9 غرف + 6 حمام + ريسيبشن 4 قطع', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'ميدان الجمهوريه', 'الجيزه', '', NULL, '', '9', NULL, NULL, 14500000.00, NULL, NULL, NULL, 'مالك', 'مونيكا', '1207544769', '', '', '', '', 30.04865560, 31.20859820),
