(96, 4, 'محل قطونيل', 'الوجهة كلادينج \r\nالمدخل سيكوريت\r\nاغلاق وفتح الباب الخارجي بالريموت \r\nحمام مياه سخن وبارد\r\nخط ارضي\r\nنظام كامل كاميرات مراقبة ٢ داخلي ٢ خارجي\r\nالمحل جاهز للتسليم براند قطونيل أو بدون\r\nالمحل يقع وسط 6 مدن كبرى: عباد الرحمن – الكندة – معادي جاردينز – الفرسان – البارون – سما.\r\nلا يوجد أي محلات بهذه المدن إلا في مدينة عباد الرحمن فقط (ميزة نادرة 👌).\r\nعلى الطريق الدائري مباشرة بجوار أكبر النوادي: نادي الصيد – القطامية جاردينز – نادي عباد – نادي الفروسية.\r\nأمام مودرن أكاديمي وبجوار برج سما على الطريق الدائري المتجه للأوتوستراد.', 'شارع أبو بكر الصديق عمارة رقم ٩  مدينة عباد الرحمن خلف نادي الصيد القطامية ومعادي جاردينز', 39.00, NULL, 'available', 'Resale', '2025-09-20 11:37:01', 7, '', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'شارع ابو بكر الصديق', 'القاهره', '', NULL, 'تسعينات', '', NULL, NULL, 2535000.00, NULL, 65000.00, NULL, 'مالك', 'الحج خالد', '1553111770', '', '', '', '', 29.98692131, 31.33624649),
