(152, 4, 'مول تجاري -اداري', '#مول_تجاري_اداري \r\n🔥افضل مول في الشيخ زايد ومدينة 6 اكتوبر \r\n✅داخل كمبوند الخمائل\r\n✅وله طريق خاص امام بوابة  كمبوند من من المحور المركزي طريق نيو جيزه \r\n✅بجوار بالم هيلز ونادي الخمائل \r\n✅لوكيشن وفيو مميز جدا فيو مفتوح علي زايد والمحور \r\n✔بمساحه مباني 2000 متر \r\n✔ومساحه ارض 1250 متر  \r\n✔ غير مساحة البدروم 19 مخزن\r\n✔ جراج + بدروم + اراضى + اول + تاني \r\n✔ غير مساحة كبيره أمام المول \r\n✔يصلح لجميع الانشطه التجاريه والمطاعم والكافيهات \r\n✔والمقرات الاداريه لكبري الشركات \r\n✔لا يمكن وصف الفيو في الصور \r\n✨المعاينه علي الطبيعه افضل \r\n✨ كمبوند الخمائل الشيخ زايد امام هايبر وان مرحلة 3 أ\r\n✔ مطلوب مقدم 115 مليون \r\n✔ باقي.  85 مليون بالفوائد على\r\n ✔ 3 سنوات ونص \r\n✔ بدون فوائد اقل من كده', 'له طريق خاص امام بوابه كمبوند من المحور المركزي', 2000.00, NULL, 'available', 'Resale', '2025-09-27 12:52:57', 7, 'جراج +بدروم +ارضي +اول +تاني', 5, NULL, NULL, 3.50, NULL, 'مول في كمبوند الخمائل', NULL, NULL, NULL, 'كمبوند الخمائل', 'الجيزه', '', NULL, '2024', '', 1250.00, NULL, NULL, 200000000.00, NULL, NULL, 'مالك', 'هاني', '1015551516', '', '', '', '', 30.01705370, 31.02376280),
(153, 1, 'عماره في كمبوند الخمائل', '1)مساحه الشقه الأرضي ٢٤٢ - مساحة بحديقه ٣٧٥\r\n2)مساحة الشقه ٢٤٢ - مساحه الحديقه ٢٠٥\r\n3)مساحة الشقه دور اول ٢٦٠متر\r\n4)مساحة الشقه دور اول ٢٦٠متر\r\n5)مساحة الشقه دور تاني ٢٦٠متر\r\n6)مساحة الشقه دور تاني ٢٦٠متر\r\n7)مساحة الشقه دور تالت ٢٦٠متر - الروف مساحة ٢٦٠ متر\r\n8) مساحة الشقه دور تالت ٢٦٠ متر - الروف مساحة ٢٦٠متر\r\n* يوجد جراج خاص في العماره - يوجد رخصة اسانسير  - العماره حصه في الأرض\r\n*العماره مطلوب مقدم  55 مليون - باقي أقساط 35 مليون على 3 سنوات ونص بالفوائد \r\n*بدون فوائد اقل من كده  - اجمالي 90 مليون', 'كمبوند الخمائل مرحلة ٣ دبل فيس', 260.00, NULL, 'available', 'Resale', '2025-09-27 13:16:50', 7, 'متاح 8 شقق الدور علي شقتين', 2, NULL, NULL, 3.50, NULL, '', 242.00, NULL, NULL, 'كمبوند الخمائل', 'الجيزه', '', 4, '', '', NULL, NULL, NULL, 90000000.00, NULL, NULL, 'مالك', 'هاني', '1015551516', '', '', '', '', 30.01705370, 31.02376280),
(154, 1, 'تاون هاوس كمبوند الخمائل', '1- مساحه الفيلا 500 متر -مساحه مباني 335 متر -مساحه حمام السباحه 26 متر \r\n2- رؤوف مكشوف 114 متر +غرفه ماستر 26 متر \r\n3-جراج يسع 5 عربيات \r\n4-الوجهات بحري وشرقي \r\n5-التشطيب (هاي لوكس )\r\n6-طرق الدفع \r\n1)كاش 26 مليون 500 ألف \r\n2) مقد 17 مليون \r\nقسط بالفوائد 30  مليون\r\nأقساط على  5 سنوات مع كمبوند \r\n✔ الفيلا تحت التشطيب \r\n✔ مفيش صور باقي على التشطيب  10 يوم \r\n✔ممكن معاينه لو في تعديل للعميل \r\nعلي التشطيب', 'موقع مرتفع باطلاله علي نادي الخمائل وأركان بلازا', 500.00, NULL, 'available', 'Resale', '2025-09-27 13:33:26', 7, '6 غرف + 5 حمامات', 5, NULL, NULL, 3.00, NULL, '', NULL, NULL, NULL, 'كمبوند الخمائل', 'الجيزه', '', 3, '', 'جراج +ارضي +اول +روف', 330.00, NULL, 26500000.00, 30000000.00, NULL, NULL, 'مالك', 'هاني', '1015551516', '', '', '', '', 30.02413270, 31.03132820),
