(175, 1, 'دوبلكس في كمبوند سيتي ڤيو', '1- مساحه الحديقه 55 م - الدور الارضي 145 م -الدور العلوي 155 م \r\n المساحة 305 متر وحديقة 55متر  تشطيب الترا سوبر لوكس الدور الارضي 145 متر: \r\nالارضية بورسلين اسباني\r\n ريسبشن  اربع قطع  وتراس على الحديقة وغرفة كبيرة مكتب وحمام ملحق به غرفة غسيل و مخزن ومطبخ مساحته 16متر \r\nالدور العلوي مساحته 155 متر:\r\nالارضيات باركيه ارو مسمار \r\nثلاث غرف نوم منهم غرفة نوم ماستر  بالچاكوزي و حمام لخدمة الغرفتين الاخريين و غرفة ناني بالحمام والشاور  \r\nوريسبشن/ ليڤنج مساحته 55 متر  مربع وتراس علي لاند سكيب \r\n \r\nعدد الغرف: ٤ (ماستر+ ٢ نوم+ غرفة اضافية)\r\nعدد الحمامات: 4 منهم چاكوزي \r\nغرفة ناني بالحمام \r\nالمنزل مجهز بساوند سيستم \r\nالكهرباء ٣ فاز \r\nعدد 3 خطوط تليفون ارضي  \r\nامن 24 ساعه وكاميرات مراقبة   \r\nمتوفر سوبر ماركت وصيدلية ومغسلة ونادي وعدد من المطاعم. \r\nالبيع  شامل \r\nثلاث غرف نوم والبلاكارات بيلت ان مصنوعة  من خشب الارو الصافي \r\n6 تكييفات منهم  2 تكييف قوة 5 حصان والباقي 3 و21/4 حصان\r\nمطبخ كامل بالاجهزة الكهربائية مصنوع من خشب البلوط بالاجهزة\r\nاثنين غرف للسائقين ( يمكن استخدامهم كمخازن او لاقامة السائقين او العاملين بالمنزل مع انتركم ) واثنين بارك لسيارتين \r\nبسعر 23مليون \r\nلو البيع بدون غرف النوم والتكييفات والمطبخ بالاجهزة وغرف السائقين واثنين بارك ب 20', 'الكمبوند قريب من المتحف المصري الجديد 4 ك فقط وقريبا المترو والمونوريل يعملون لخدمة المتحف', 305.00, NULL, 'available', 'Resale', '2025-10-06 15:03:12', 7, '5 غرف + 6 حمامات +ريسبشن 6 قطع', 6, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'كمبوند سيتي ڤيو', 'القاهره', '', NULL, '0', 'ارضي بجاردن واول', NULL, NULL, 23000000.00, NULL, NULL, NULL, 'مالك', 'سنيه', '1149555588', '', '', '', '', 30.01295620, 31.09598310),
(176, 1, 'شقه شارع عبدالحميد لطفي', '1-دور خامس اخير اسانسير بيطلع للرابع وفي دور واحد فقط سلم\r\n2- بها ٢ تكييف ومطبخ راكب  وسخان. \r\n3-هي بتبص عالبطل من الجنب وبتبص علي ش عبدالحميد لطفي وش الاشجار من الغرف', 'موقع بالمهندسين بشارع عبدالحميد لطفي اول عماره من ناحيه البطل احمد عبد العزيز', 155.00, NULL, 'available', 'Resale', '2025-10-06 15:11:44', 7, '3 غرف + 2 حمام', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'تفرعات البطل احمد عبد العزيز', 'الجيزه', '', 5, 'تسعينات', '5', 120.00, NULL, 3750000.00, NULL, NULL, NULL, 'مالك', 'هاني', '1224057810', '', '', '', '', 30.05176650, 31.20655420),
