(179, 1, 'كمبوند زايد هايتس', '1-العمارة جنب البوابة الشغل اعلي مستوي - الواجهة معمولة حجر \r\n2- الرسيبشن 50 متر 7*7 - الغرفة الرئيسية ماستر + دريسنج \r\n3- متاح مكان الاسانسير لكن لم يتم التركيب حتي الان \r\n4- الجراج بسعر منفصل 350 الف اختياري\r\n5- العمولة 1.25- السعر نهائي \r\n6- عداد كهرباء كارت', '123 أ كمبوند زايد هايتس مدخل زايد 3', 208.00, NULL, 'available', 'Resale', '2025-10-13 15:23:17', 13, '3غرف +3 حمام', 2, NULL, 75.00, 1.00, NULL, '', NULL, NULL, NULL, 'الشيخ زايد', 'الجيزة', '', 5, '2024', 'اول علوي', NULL, NULL, 5200000.00, 5200000.00, NULL, NULL, 'مالك', 'مهندس عزت حسين', '1156444619', '', '', '', '', 30.01790950, 30.98085650),
(180, 1, 'بيت الوطن 6 اكتوبر', '1- العمولة 1% \r\n2- بيسلمو بالابواب \r\n3- بيجيبو العدادات و العميل يحاسب عليها \r\n4 - متاح 2 شقة بنفس التفاصيل', 'الحي التاسع 6 اكتوبر بيت الوطن', 200.00, NULL, 'available', 'Resale', '2025-10-14 10:47:44', 13, '3 غرف + 2 حمام', 2, NULL, NULL, 1.00, NULL, '', NULL, NULL, NULL, '6 اكتوبر', 'الجيزة', 'شركة الشهداء', NULL, '', 'ارضي بجاردن', NULL, NULL, 5000000.00, 5300000.00, NULL, NULL, 'شركة مطورة', 'مهندس محمد ابو السعود', '01008333910 - 01000017271', '', '', '', '', NULL, NULL),
(181, 1, 'كمبوند زايد هايتس', '1- شركة نسويق و التعامل كل واحد وعمولته \r\n2 - تراس بحري علي الشارع الرئيسي خطوات من جيت وان - تاني بلكونة بحرية علي محور وصلة دهشور دبل فيو \r\n3- رسيبشن 3 قطع - الغرفة الماستر مزودة بدرسينج و حمام \r\n4- العمارة مزودة باسانسير \r\n5 - مدخل العمارة ارضيات و حوائط رخام و جرانيت و سقف جبسمبورد', 'كمبوند زايد هايتس مدخل زايد 3', 245.00, NULL, 'available', 'Resale', '2025-10-14 11:32:16', 13, '4 غرف + 3 حمام', 2, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'الشيخ زايد', 'الجيزة', 'شركة انجاز للتنمية العقارية', NULL, '0', 'الثاني', NULL, NULL, 6250000.00, NULL, NULL, NULL, 'شركة تسويق', 'مهندس محمد خليفة', '1066442992', '', '', '', '', 30.01782540, 30.97616480),
(182, 1, 'كمبوند زايد هايتس', '1- العمولة كل شركة من العميل بتاعها \r\n2- ارضي بجاردن مدخل خاص - الحديقة حق انتفاع مساحتها 150 متر \r\n3- رسبشن 3 قطع - غرفة ماستر بدريسنج و حمام \r\n4- الحديقة بها مكان يسع لركن سيارتين', 'كمبوند زايد هايتس', 235.00, NULL, 'available', 'Resale', '2025-10-14 13:30:51', 13, '4 غرف + 3 حمام', 5, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'الشيخ زايد', 'الجيزة', 'شركة انجاز للتنمية العقارية', NULL, '0', 'ارضي بجاردن', NULL, NULL, 7500000.00, NULL, NULL, NULL, 'شركة تسويق', 'مهندس محمد خليفة', '1066442992', '', '', '', '', 30.01782540, 30.97616480),
(184, 1, 'كمبوند زايد هايتس', '1- العمولة كل شركة من عميلها \r\n2- دبل فيس علي شارع الصفا خطوات من بوابة الكمبوند الرئيسية - العمارة مزودة باسانسير \r\n3- رسبشن 3قطع حرف L - الغرفة الماستر مزودة بحمام و دريسنج', 'كمبوند زايد هايتس مدخل زايد 3', 236.00, NULL, 'available', 'Resale', '2025-10-14 14:41:37', 13, '4 غرف + 3 حمام', 2, NULL, NULL, NULL, NULL, '', NULL, NULL, NULL, 'الشيخ زايد', 'الجيزة', 'شركة انجاز للتنمية العقارية', NULL, '', '', NULL, NULL, 6700000.00, NULL, NULL, NULL, 'شركة تسويق', 'مهندس محمد خليفة', '1066442992', '', '', '', '', 30.01782540, 30.97616480),
